mapper.select:
select d.sn, d.user_id AS userId, u.user_name AS userName, d.model,
       d.last_online_time AS lastOnlineTime, d.accumulated_voyage AS accumulatedVoyage,
       d.fly_time AS flyTime, d.flight_controller_serial_number AS flightControllerSerialNumber,
       d.create_time AS createTime, d.modification_time AS modificationTime
from devices d left join users u on d.user_id = u.user_id

    and d.user_id = #{userId}
    and d.sn = #{snCode}

order by d.create_time desc limit #{offset},#{size}

select count(*) from devices d

    and d.user_id = #{userId}
    and d.sn = #{snCode}
